// В 99% вызовов сюда приходит List<int>.
// Без профиля каждый шаг foreach — интерфейсный вызов,
// с профилем Tier 1 сделает быстрый путь под List<int>.
static int Sum(IEnumerable<int> items)
{
    int s = 0;
    foreach (var x in items) s += x;
    return s;
}

