static readonly bool s_trace =
    Environment.GetEnvironmentVariable("TRACE") == "1";

static int Work(int x)
{
    if (s_trace)               // в Tier 1 — константа
        Console.WriteLine(x);  // при false ветки не будет
    return x * 2;
}
